        .unwrap()
}

/// T08: a matching `If-Match` updates both views and rotates the ETag.
#[tokio::test]
async fn put_update_matching_etag_succeeds_and_rotates_etag() {
    let (
        temp_dir,
        pool,
        accounts,
        user_id,
        password,
        principal_id,
        calendar_id,
        event_id,
        resource_name,
    ) = scenario().await;

